import { useCallback, useEffect, useMemo, useRef, useState } from "react";

interface PanelProps { projectId: string }
interface Artifact { id:number; kind:string; format:string; name:string; size_bytes:number; storage_file_id?:string }
interface Check { code:string; severity:"error"|"warning"; message:string; object_ids?:string[] }
interface Validation { status:string; errors:number; warnings:number; report:{ checks:Check[] } }
interface Revision { id:number; number:number; source_sha256:string; definition:Definition }
interface Design { id:number; name:string; status:string; current_revision_id:number; current_revision?:Revision; validation?:Validation; artifacts?:Artifact[]; updated_at:string }
interface Point { x_nm:number; y_nm:number }
interface MechanicalSpec { schema:string;datum:{origin:string;handedness:string;x_axis:string;y_axis:string;z_axis:string};tolerances?:{xy_nm:number;z_nm:number;panel_opening_fit_nm:number;fastener_fit_nm:number};mounting_holes:{id:string;x_nm:number;y_nm:number;diameter_nm:number;plated:boolean;fastener?:string;head_clearance_nm?:number;position_tolerance_nm?:number;diameter_tolerance_nm?:number}[];component_envelopes:{id:string;component_id?:string;kind?:string;shape?:string;model_ref?:string;label?:string;x_nm:number;y_nm:number;z_min_nm:number;z_max_nm:number;width_nm:number;depth_nm:number;rotation_udeg?:number;tolerance_nm?:number}[];panel_openings:{id:string;component_id?:string;kind?:string;face:string;x_nm:number;y_nm:number;z_nm:number;width_nm:number;height_nm:number;radius_nm?:number;depth_nm?:number;tolerance_nm?:number}[];clearance_zones:{id:string;owner_id?:string;kind:string;x_nm:number;y_nm:number;z_min_nm:number;z_max_nm:number;width_nm:number;depth_nm:number;rotation_udeg?:number}[] }
interface MechanicalValidation { status:string;errors:number;warnings:number;checks:Check[];metrics:Record<string,number> }
interface Pad { id:string;pin_id:string;shape:"rect"|"roundrect"|"circle"|"oval";x_nm:number;y_nm:number;width_nm:number;height_nm:number;drill_nm?:number;layers:string[] }
interface Definition {
  schema:string; name?:string;
  board:{ width_nm:number; height_nm:number; thickness_nm?:number; corner_radius_nm?:number; outline?:Point[]; cutouts?:{id:string;kind:string;x_nm:number;y_nm:number;width_nm?:number;height_nm?:number;diameter_nm?:number;rotation_udeg?:number;polygon?:Point[]}[]; layers:{id:string;kind:string;order:number}[] };
  rules:{ min_clearance_nm:number; min_trace_width_nm:number; min_edge_clearance_nm:number;min_drill_nm?:number;min_annular_ring_nm?:number };
  components:{ id:string;designator:string;name:string;value?:string;mpn?:string;footprint?:string;position:{x_nm:number;y_nm:number;rotation_udeg:number;side:string};body?:{width_nm:number;height_nm:number};pins?:unknown[];pads?:Pad[] }[];
  nets:{id:string;name:string;nodes?:unknown[]}[];
  traces:{id:string;net_id:string;layer:string;width_nm:number;points:Point[]}[];
  vias:{id:string;net_id:string;x_nm:number;y_nm:number;diameter_nm:number;drill_nm:number;from_layer:string;to_layer:string}[];
  zones?:{id:string;net_id:string;layer:string;clearance_nm?:number;polygon:Point[]}[];
  keepouts?:{id:string;kind:string;layer?:string;owner_id?:string;polygon:Point[]}[];
  differential_pairs?:{id:string;positive_net_id:string;negative_net_id:string;target_ohms?:number;gap_nm:number;gap_tolerance_nm?:number;max_skew_nm:number}[];
  net_classes?:{id:string;net_ids:string[];trace_width_nm?:number;clearance_nm?:number;via_diameter_nm?:number;via_drill_nm?:number;priority?:number}[];
  simulation?:unknown;
  wiring?:WiringSpec;
  mechanical?:MechanicalSpec;
}
interface RoutePlan { status:string;grid_nm:number;routed_nets:string[];skipped_nets?:string[];failures?:{net_id:string;message:string}[];operations:{type:string;trace?:Definition["traces"][number];via?:Definition["vias"][number]}[];metrics:{requested_nets:number;routed_nets:number;skipped_nets:number;trace_count:number;via_count:number;total_length_nm:number;visited_nodes:number} }
interface SimulationResult { status:string;duration_us:number;step_us:number;samples:number;final_voltage_v:Record<string,number>;final_digital:Record<string,string>;waveforms:{probe_id:string;net_id:string;kind:string;unit:string;points:{time_us:number;value:number;digital?:string}[]}[];device_states?:Record<string,unknown>[];warnings?:string[] }
interface FirmwareResult { status:string;runtime:string;board:string;duration_us:number;serial_baud?:number;serial_output:string[];pin_states:Record<string,string>;i2c_transactions:{time_us:number;address:number;bytes:number[];status:string}[];warnings?:string[] }
interface WiringSpec { schema:string;canvas:{width:number;height:number;grid?:number};parts:{id:string;library_id:string;label?:string;x:number;y:number;rotation_deg?:number;properties?:Record<string,unknown>}[];wires:{id:string;net_id:string;color?:string;from:{part_id:string;pin_id:string};to:{part_id:string;pin_id:string};points?:{x:number;y:number}[]}[];annotations?:{id:string;text:string;x:number;y:number}[];steps?:{id:string;title:string;instruction:string;part_ids?:string[];wire_ids?:string[]}[];firmware?:{board:string;source:string;pin_map?:Record<string,string>} }
interface WiringSimulation { status:string;board:string;firmware:FirmwareResult;part_states:Record<string,{active?:boolean;brightness?:number;color?:string}> }
interface FabricationVerification { status:string;errors:number;checks:Check[];files:{path:string;kind:string;bytes:number;apertures?:number;draws?:number;regions?:number;drill_tools?:number;holes?:number}[];summary:Record<string,number> }
interface ProductionReadiness { status:string;errors:number;warnings:number;checks:Check[];metrics:Record<string,number>;physical_validation:string;next_action:string }

const API="/api/apps/pcb/api";
const TEMPLATE:Definition={schema:"apteva-pcb/v1",name:"Controller board",board:{width_nm:50000000,height_nm:30000000,layers:[{id:"F.Cu",kind:"copper",order:0},{id:"B.Cu",kind:"copper",order:1},{id:"F.SilkS",kind:"silkscreen",order:2}]},rules:{min_clearance_nm:200000,min_trace_width_nm:200000,min_edge_clearance_nm:250000,min_drill_nm:200000,min_annular_ring_nm:125000},components:[{id:"u1",designator:"U1",name:"Microcontroller",value:"RP2040",mpn:"RP2040",footprint:"QFN-56",position:{x_nm:25000000,y_nm:15000000,rotation_udeg:0,side:"front"},body:{width_nm:7000000,height_nm:7000000},pins:[{id:"1",number:"1",name:"IO0",electrical_type:"bidirectional",pad:"1"}],pads:[{id:"1",pin_id:"1",shape:"roundrect",x_nm:-3500000,y_nm:0,width_nm:900000,height_nm:400000,layers:["F.Cu"]}]},{id:"j1",designator:"J1",name:"Connector",value:"USB-C",footprint:"USB-C-16P",position:{x_nm:5000000,y_nm:15000000,rotation_udeg:0,side:"front"},body:{width_nm:8000000,height_nm:9000000},pins:[{id:"1",number:"1",name:"D+",electrical_type:"bidirectional",pad:"1"}],pads:[{id:"1",pin_id:"1",shape:"roundrect",x_nm:4000000,y_nm:0,width_nm:900000,height_nm:400000,layers:["F.Cu"]}]}],nets:[{id:"usb-dp",name:"USB_D+",nodes:[{component_id:"u1",pin_id:"1"},{component_id:"j1",pin_id:"1"}]}],traces:[{id:"usb-dp-1",net_id:"usb-dp",layer:"F.Cu",width_nm:250000,points:[{x_nm:9000000,y_nm:15000000},{x_nm:21500000,y_nm:15000000}]}],vias:[],zones:[],keepouts:[],differential_pairs:[]};
function url(path:string,projectId:string){return `${API}${path}${path.includes("?")?"&":"?"}project_id=${encodeURIComponent(projectId)}`}
async function request(path:string,projectId:string,init?:RequestInit){const response=await fetch(url(path,projectId),{credentials:"same-origin",...init,headers:{"Content-Type":"application/json",...(init?.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||response.statusText);return body}
const mm=(nm:number)=>nm/1e6;
const DEFAULT_FIRMWARE=`#include <Wire.h>

void setup() {
  Serial.begin(115200);
  Wire.begin();
  Wire.beginTransmission(0x70);
  Wire.write(0x7C);
  Wire.endTransmission();
  pinMode(8, OUTPUT);
}

void loop() {
  float temperature = sensor.readTemperature();
  float humidity = sensor.readHumidity();
  Serial.print("Temperature: ");
  Serial.println(temperature);
  Serial.print("Humidity: ");
  Serial.println(humidity);
  digitalWrite(8, HIGH);
  delay(1000);
}`;

export default function PCBPanel({projectId}:PanelProps){
  const [designs,setDesigns]=useState<Design[]>([]),[selectedId,setSelectedId]=useState<number|null>(null),[design,setDesign]=useState<Design|null>(null);
  const [source,setSource]=useState(JSON.stringify(TEMPLATE,null,2)),[newName,setNewName]=useState("Controller board"),[note,setNote]=useState("");
  const [tab,setTab]=useState<"board"|"mechanical"|"wiring"|"route"|"simulate"|"firmware"|"source">("board"),[busy,setBusy]=useState(""),[error,setError]=useState("");
  const [routePlan,setRoutePlan]=useState<RoutePlan|null>(null),[simulation,setSimulation]=useState<SimulationResult|null>(null),[firmware,setFirmware]=useState<FirmwareResult|null>(null),[firmwareSource,setFirmwareSource]=useState(DEFAULT_FIRMWARE),[verification,setVerification]=useState<FabricationVerification|null>(null),[readiness,setReadiness]=useState<ProductionReadiness|null>(null),[wiringSimulation,setWiringSimulation]=useState<WiringSimulation|null>(null),[mechanicalValidation,setMechanicalValidation]=useState<MechanicalValidation|null>(null);
  const [undoStack,setUndoStack]=useState<string[]>([]),[redoStack,setRedoStack]=useState<string[]>([]);
  const parsed=useMemo(()=>{try{return JSON.parse(source) as Definition}catch{return null}},[source]);
  const loadDesigns=useCallback(async()=>{const body=await request("/designs?status=all",projectId);setDesigns(body.designs||[]);if(!selectedId&&body.designs?.length)setSelectedId(body.designs[0].id)},[projectId,selectedId]);
  const loadDesign=useCallback(async(id:number)=>{const body=await request(`/designs/${id}`,projectId);const definition=body.design.current_revision?.definition||TEMPLATE;setDesign(body.design);setSource(JSON.stringify(definition,null,2));setUndoStack([]);setRedoStack([]);setRoutePlan(null);setVerification(null);setReadiness(null);setMechanicalValidation(null);if(definition.mechanical)setTab("mechanical")},[projectId]);
  useEffect(()=>{loadDesigns().catch(e=>setError(e.message))},[loadDesigns]);useEffect(()=>{if(selectedId)loadDesign(selectedId).catch(e=>setError(e.message))},[selectedId,loadDesign]);
  async function run(label:string,fn:()=>Promise<void>){setBusy(label);setError("");try{await fn()}catch(e){setError((e as Error).message)}finally{setBusy("")}}
  function create(){if(!parsed)return setError("The native PCB JSON is not valid.");run("Creating",async()=>{const body=await request("/designs",projectId,{method:"POST",body:JSON.stringify({name:newName,definition:parsed,note:"Initial native board"})});await loadDesigns();setSelectedId(body.design.id)})}
  function createWiringExample(){run("Creating Arduino tutorial",async()=>{const body=await request("/wiring/examples/arduino-led",projectId,{method:"POST",body:JSON.stringify({name:"Arduino Uno · LED breadboard tutorial",note:"Native PCB Studio wiring example"})});await loadDesigns();setSelectedId(body.design.id);setTab("wiring")})}
  function createMechanicalExample(){run("Creating Raspberry Pi mechanical model",async()=>{const body=await request("/mechanical/examples/raspberry-pi-4",projectId,{method:"POST",body:JSON.stringify({name:"Raspberry Pi 4 · Mechanical Enclosure Reference",note:"Native PCB Studio mechanical proof"})});await loadDesigns();setSelectedId(body.design.id);setTab("mechanical")})}
  function createDHTExample(){run("Creating DHT22 sensor node",async()=>{const body=await request("/mechanical/examples/dht22-node",projectId,{method:"POST",body:JSON.stringify({name:"ESP32-C3 DHT22 Environmental Sensor Node",note:"Routed USB-C sensor board with native 3D mechanical geometry"})});await loadDesigns();setSelectedId(body.design.id);setTab("mechanical")})}
  function save(){if(!design||!parsed)return setError("Select a design and fix the source JSON first.");run("Saving revision",async()=>{await request(`/designs/${design.id}/revisions`,projectId,{method:"POST",body:JSON.stringify({expected_parent_id:design.current_revision_id,definition:parsed,note})});setNote("");await loadDesign(design.id);await loadDesigns()})}
  function action(name:string,label:string){if(!design)return;run(label,async()=>{await request(`/designs/${design.id}/${name}`,projectId,{method:"POST",body:"{}"});await loadDesign(design.id)})}
  function suggestRoute(){if(!design)return;run("Analyzing routes",async()=>{const body=await request(`/designs/${design.id}/route-suggest`,projectId,{method:"POST",body:JSON.stringify({options:{grid_nm:500000,layers:["F.Cu","B.Cu"]}})});setRoutePlan(body.plan);setTab("route")})}
  function applyRoute(){if(!design||!routePlan)return;run("Applying route revision",async()=>{await request(`/designs/${design.id}/route-apply`,projectId,{method:"POST",body:JSON.stringify({options:{grid_nm:routePlan.grid_nm,layers:["F.Cu","B.Cu"]},note:"PCB Studio 0.5 native autoroute"})});setRoutePlan(null);await loadDesign(design.id);await loadDesigns();setTab("board")})}
  function runSimulation(){if(!design)return;run("Running simulation",async()=>{const body=await request(`/designs/${design.id}/simulate`,projectId,{method:"POST",body:JSON.stringify({options:{duration_us:10000,step_us:100}})});setSimulation(body.result);await loadDesign(design.id);setTab("simulate")})}
  function runFirmware(){if(!design)return;run("Running virtual firmware",async()=>{const body=await request(`/designs/${design.id}/firmware`,projectId,{method:"POST",body:JSON.stringify({options:{source:firmwareSource,language:"arduino",iterations:2}})});setFirmware(body.result);await loadDesign(design.id);setTab("firmware")})}
  function exportWiring(format:string){if(!design)return;run(`Exporting wiring ${format}`,async()=>{await request(`/designs/${design.id}/wiring-export`,projectId,{method:"POST",body:JSON.stringify({format})});await loadDesign(design.id);setTab("wiring")})}
  function runWiring(){if(!design)return;run("Running wired Arduino",async()=>{const body=await request(`/designs/${design.id}/wiring-simulate`,projectId,{method:"POST",body:JSON.stringify({iterations:1})});setWiringSimulation(body.result);await request(`/designs/${design.id}/wiring-export`,projectId,{method:"POST",body:JSON.stringify({format:"svg"})});await loadDesign(design.id);setTab("wiring")})}
  function validateMechanical(){if(!design)return;run("Validating mechanical envelope",async()=>{const body=await request(`/designs/${design.id}/mechanical-validate`,projectId,{method:"POST",body:"{}"});setMechanicalValidation(body);setTab("mechanical")})}
  function exportMechanical(kind:"preview"|"export"|"step"|"stl"|"3mf"|"dxf"){if(!design)return;const solid=!(["preview","export"] as string[]).includes(kind);run(solid?`Exporting mechanical ${kind.toUpperCase()}`:kind==="preview"?"Rendering 3D mechanical preview":"Exporting mechanical envelope",async()=>{await request(`/designs/${design.id}/${solid?"mechanical-solid":`mechanical-${kind}`}`,projectId,{method:"POST",body:solid?JSON.stringify({format:kind}):"{}"});await loadDesign(design.id);setTab("mechanical")})}
  function verifyFabrication(){if(!design)return;run("Parsing fabrication files",async()=>{const body=await request(`/designs/${design.id}/manufacturing-verify`,projectId,{method:"POST",body:"{}"});setVerification(body.result);if(body.artifact)setDesign(current=>current?{...current,artifacts:[body.artifact,...(current.artifacts||[]).filter(a=>a.id!==body.artifact.id)]}:current)})}
  function runReadiness(){if(!design)return;run("Running production-readiness gate",async()=>{const body=await request(`/designs/${design.id}/production-readiness`,projectId,{method:"POST",body:"{}"});setReadiness(body.result);if(body.artifact)setDesign(current=>current?{...current,artifacts:[body.artifact,...(current.artifacts||[]).filter(a=>a.id!==body.artifact.id)]}:current)})}
  function exportKiCad(){if(!design)return;run("Exporting verified KiCad board",async()=>{await request(`/designs/${design.id}/kicad-export`,projectId,{method:"POST",body:"{}"});await loadDesign(design.id)})}
  function editDefinition(next:Definition,label:string){const serialized=JSON.stringify(next,null,2);if(serialized===source)return;setUndoStack(items=>[...items.slice(-49),source]);setRedoStack([]);setSource(serialized);setNote(label)}
  function undoEdit(){setUndoStack(items=>{if(!items.length)return items;const previous=items[items.length-1];setRedoStack(next=>[...next.slice(-49),source]);setSource(previous);setNote("Undo layout edit");return items.slice(0,-1)})}
  function redoEdit(){setRedoStack(items=>{if(!items.length)return items;const next=items[items.length-1];setUndoStack(previous=>[...previous.slice(-49),source]);setSource(next);setNote("Redo layout edit");return items.slice(0,-1)})}
  const validation=design?.validation,artifacts=design?.artifacts||[],wiringArtifact=artifacts.find(a=>a.kind==="wiring"&&a.format==="svg");
  const savedSource=design?.current_revision?JSON.stringify(design.current_revision.definition,null,2):source;
  const hasStaged=!!design&&source!==savedSource;
  return <div className="pcb-root" data-wiring={tab==="wiring"} data-mechanical={tab==="mechanical"}>
    <header className="pcb-header"><div className="pcb-logo"><PCBMark/></div><div className="pcb-title"><h1>PCB Studio</h1><p>Native electronics design · mechanical · wire · route · simulate · fabricate</p></div><span className="engine-pill"><i/>Apteva PCB 0.9</span><span className="grow"/><div className="action-group"><button onClick={suggestRoute} disabled={!design||!!busy||hasStaged}>Autoroute</button><button onClick={runSimulation} disabled={!design||!!busy||hasStaged}>Simulate</button><button onClick={validateMechanical} disabled={!parsed?.mechanical||!!busy||hasStaged}>Mechanical</button><button onClick={()=>action("validate","Validating")} disabled={!design||!!busy||hasStaged}>DRC</button><button onClick={verifyFabrication} disabled={!design||!!busy||hasStaged}>Verify fab</button><button onClick={runReadiness} disabled={!design||!!busy||hasStaged}>Readiness</button></div><button className="primary" onClick={()=>action("release","Creating release")} disabled={!design||!!busy||hasStaged}>Create release</button></header>
    {busy&&<div className="progress"/>}{error&&<div className="error">{error}</div>}
    <div className="pcb-grid">
      <aside className="library"><Label>Designs</Label>{designs.map(d=><button className="design-item" data-active={selectedId===d.id} onClick={()=>setSelectedId(d.id)} key={d.id}><strong>{d.name}</strong><small>{d.status} · r{d.id===design?.id?design.current_revision?.number:"—"}</small></button>)}{!designs.length&&<p className="muted">No designs yet.</p>}<div className="new"><Label>Start a design</Label><button className="example-card mechanical-example" disabled={!!busy} onClick={createDHTExample}><span>DHT22 Sensor Node</span><small>ESP32-C3 · USB-C · JST · routed PCB</small></button><button className="example-card mechanical-example" disabled={!!busy} onClick={createMechanicalExample}><span>Raspberry Pi 4</span><small>Mechanical · 3D envelope · enclosure handoff</small></button><button className="example-card" disabled={!!busy} onClick={createWiringExample}><span>Arduino Uno + LED</span><small>Breadboard · 220 Ω · pin 9</small></button><input value={newName} onChange={e=>setNewName(e.target.value)}/><button className="primary wide" disabled={!parsed||!newName.trim()||!!busy} onClick={create}>Create from editor</button></div></aside>
      <main className="workspace"><div className="tabs"><button data-active={tab==="board"} onClick={()=>setTab("board")}>Layout</button><button data-active={tab==="mechanical"} onClick={()=>setTab("mechanical")}>Mechanical</button><button data-active={tab==="wiring"} onClick={()=>setTab("wiring")}>Wiring</button><button data-active={tab==="route"} onClick={()=>setTab("route")}>Route</button><button data-active={tab==="simulate"} onClick={()=>setTab("simulate")}>Simulate</button><button data-active={tab==="firmware"} onClick={()=>setTab("firmware")}>Firmware</button><button data-active={tab==="source"} onClick={()=>setTab("source")}>Source</button><span className="grow"/>{design?.current_revision&&<code>{hasStaged?`${Math.max(1,undoStack.length)} staged · `:""}revision {design.current_revision.number} · {design.current_revision.source_sha256.slice(0,10)}</code>}</div>{tab==="board"?<BoardCanvas definition={parsed||TEMPLATE} onChange={editDefinition} onUndo={undoEdit} onRedo={redoEdit} canUndo={undoStack.length>0} canRedo={redoStack.length>0}/>:tab==="mechanical"?<MechanicalLab definition={parsed||TEMPLATE} validation={mechanicalValidation} onChange={editDefinition} onValidate={validateMechanical} onPreview={()=>exportMechanical("preview")} onExport={()=>exportMechanical("export")} onSolid={format=>exportMechanical(format)} disabled={!design||!!busy}/>:tab==="wiring"?<WiringLab definition={parsed||TEMPLATE} preview={wiringArtifact?url(`/artifacts/${wiringArtifact.id}/content`,projectId):""} result={wiringSimulation} onRun={runWiring} onExport={exportWiring} disabled={!design||!!busy||hasStaged}/>:tab==="route"?<RouteLab definition={parsed||TEMPLATE} plan={routePlan} onAnalyze={suggestRoute} onApply={applyRoute} disabled={!design||!!busy||hasStaged}/>:tab==="simulate"?<SimulationLab result={simulation} onRun={runSimulation} disabled={!design||!!busy||hasStaged}/>:tab==="firmware"?<FirmwareLab source={firmwareSource} setSource={setFirmwareSource} result={firmware} onRun={runFirmware} disabled={!design||!!busy||hasStaged}/>:<textarea spellCheck={false} value={source} onChange={e=>setSource(e.target.value)}/>}</main>
      <aside className="inspector"><Section title="Revision"><textarea className="note" placeholder="What changed?" value={note} onChange={e=>setNote(e.target.value)}/><button className="primary wide" onClick={save} disabled={!design||!parsed||!!busy}>Save immutable revision</button></Section><Section title="Native graph"><Row label="Board" value={parsed?`${mm(parsed.board.width_nm)} × ${mm(parsed.board.height_nm)} mm`:"—"}/><Row label="Layers / net classes" value={`${parsed?.board.layers.length||0} / ${parsed?.net_classes?.length||0}`}/><Row label="Components / pads" value={`${parsed?.components.length||0} / ${parsed?.components.reduce((n,c)=>n+(c.pads?.length||0),0)||0}`}/><Row label="Nets" value={String(parsed?.nets.length||0)}/><Row label="Traces / vias" value={`${parsed?.traces.length||0} / ${parsed?.vias.length||0}`}/><Row label="Zones / keepouts" value={`${parsed?.zones?.length||0} / ${parsed?.keepouts?.length||0}`}/><Row label="Differential pairs" value={String(parsed?.differential_pairs?.length||0)}/></Section><Section title="Validation"><div className={`status ${validation?.status||"idle"}`}>● {validation?.status||"not run"}{validation&&` · ${validation.errors} errors · ${validation.warnings} warnings`}</div>{validation?.report.checks.slice(0,12).map((c,i)=><div className="check" key={i} data-severity={c.severity}><b>{c.severity==="error"?"×":"!"}</b><span>{c.message}<small>{c.code}</small></span></div>)}</Section><Section title="Fabrication parser"><div className={`status ${verification?.status||"idle"}`}>● {verification?.status||"not run"}{verification&&` · ${verification.files.length} files · ${verification.summary.draws||0} draws · ${verification.summary.holes||0} holes`}</div>{verification?.checks.slice(0,8).map((c,i)=><div className="check" key={i} data-severity={c.severity}><b>×</b><span>{c.message}<small>{c.code}</small></span></div>)}<button className="wide" onClick={verifyFabrication} disabled={!design||!!busy||hasStaged}>Parse generated files</button></Section><Section title="Production gate"><div className={`status ${readiness?.status==="blocked"?"failed":readiness?"passed":"idle"}`}>● {readiness?.status||"not run"}{readiness&&` · ${readiness.errors} blockers · ${readiness.metrics.test_points||0} test nets`}</div>{readiness?.checks.slice(0,5).map((c,i)=><div className="check" key={i} data-severity={c.severity}><b>{c.severity==="error"?"×":"!"}</b><span>{c.message}<small>{c.code}</small></span></div>)}<button className="wide" onClick={runReadiness} disabled={!design||!!busy||hasStaged}>Run readiness gate</button><button className="wide" onClick={exportKiCad} disabled={!design||!!busy||hasStaged}>Export verified KiCad</button></Section><Section title="Artifacts">{artifacts.map(a=><a className="artifact" key={a.id} href={url(`/artifacts/${a.id}/content`,projectId)}><b>{a.kind==="manufacturing"?"fab":a.kind==="verification"?"check":a.kind==="production-readiness"?"gate":a.kind.includes("kicad")?"pcb":a.kind==="simulation"?"sim":a.kind==="firmware"?"mcu":a.format}</b><span>{a.name}</span><small>{a.storage_file_id?"Storage":"local"} · {Math.max(1,Math.round(a.size_bytes/1024))}K</small></a>)}{!artifacts.length&&<p className="muted">Previews, simulations, firmware runs, fabrication files, and releases appear here and in Storage.</p>}</Section></aside>
    </div><style>{styles}{labStyles}{wiringStyles}{mechanicalStyles}{editorStyles}</style>
  </div>
}

function MechanicalLab({definition,validation,onChange,onValidate,onPreview,onExport,onSolid,disabled}:{definition:Definition;validation:MechanicalValidation|null;onChange:(next:Definition,label:string)=>void;onValidate:()=>void;onPreview:()=>void;onExport:()=>void;onSolid:(format:"step"|"stl"|"3mf"|"dxf")=>void;disabled:boolean}){
  const mechanical=definition.mechanical,[yaw,setYaw]=useState(-34),[elevation,setElevation]=useState(27),[showClearance,setShowClearance]=useState(false),[showInterfaces,setShowInterfaces]=useState(false),[showLabels,setShowLabels]=useState(false),[details,setDetails]=useState(false),[selected,setSelected]=useState("");
  if(!mechanical)return <div className="lab mechanical-empty"><div className="empty-lab"><b>No mechanical envelope</b><p>Add an <code>apteva-pcb-mechanical/v1</code> block or create the Raspberry Pi 4 reference from the left rail.</p></div></div>;
  const thickness=(definition.board.thickness_nm||1600000)/1e6,outline=(definition.board.outline?.length?definition.board.outline:[{x_nm:0,y_nm:0},{x_nm:definition.board.width_nm,y_nm:0},{x_nm:definition.board.width_nm,y_nm:definition.board.height_nm},{x_nm:0,y_nm:definition.board.height_nm}]);
  const scale=Math.min(details?5.5:7.1,(details?480:610)/Math.max(mm(definition.board.width_nm),mm(definition.board.height_nm))),rad=yaw*Math.PI/180,pitch=elevation*Math.PI/180;
  const project=(x:number,y:number,z:number):[number,number]=>{x-=mm(definition.board.width_nm)/2;y-=mm(definition.board.height_nm)/2;const rx=x*Math.cos(rad)-y*Math.sin(rad),ry=x*Math.sin(rad)+y*Math.cos(rad);return [(details?390:450)+rx*scale,330+(ry*Math.sin(pitch)-z*Math.cos(pitch))*scale]};
  const points=(items:Point[],z:number)=>items.map(p=>project(mm(p.x_nm),mm(p.y_nm),z).map(v=>v.toFixed(1)).join(",")).join(" ");
  function revise(mutator:(next:Definition)=>void,label:string){const next=JSON.parse(JSON.stringify(definition)) as Definition;mutator(next);onChange(next,label)}
  function setHeight(id:string,value:number){if(!Number.isFinite(value)||value<=0)return;revise(next=>{const item=next.mechanical?.component_envelopes.find(e=>e.id===id);if(item)item.z_max_nm=item.z_min_nm+Math.round(value*1e6)},`Set ${id} mechanical height`)}
  function addHole(){revise(next=>{const m=next.mechanical!;m.mounting_holes.push({id:uniqueUIID(m.mounting_holes.map(v=>v.id),"mh-"),x_nm:Math.round(next.board.width_nm/2),y_nm:Math.round(next.board.height_nm/2),diameter_nm:2700000,plated:false,fastener:"M2.5",head_clearance_nm:5000000})},"Add mounting hole")}
  function addOpening(){revise(next=>{const m=next.mechanical!;m.panel_openings.push({id:uniqueUIID(m.panel_openings.map(v=>v.id),"opening-"),kind:"custom",face:"east",x_nm:next.board.width_nm,y_nm:Math.round(next.board.height_nm/2),z_nm:5000000,width_nm:10000000,height_nm:7000000,depth_nm:3000000})},"Add connector opening")}
  function addClearance(){revise(next=>{const m=next.mechanical!;m.clearance_zones.push({id:uniqueUIID(m.clearance_zones.map(v=>v.id),"clear-"),kind:"airflow",x_nm:Math.round(next.board.width_nm/2),y_nm:Math.round(next.board.height_nm/2),z_min_nm:next.board.thickness_nm||1600000,z_max_nm:20000000,width_nm:20000000,depth_nm:20000000})},"Add clearance volume")}
  const selectedEnvelope=mechanical.component_envelopes.find(e=>e.id===selected);
  return <div className="mechanical-lab">
    <div className="mechanical-toolbar"><div><small>Native mechanical assembly</small><strong>PCB envelope · toleranced · revisioned</strong></div><div className="mech-metrics"><span><b>{mm(definition.board.width_nm)} × {mm(definition.board.height_nm)}</b><small>board mm</small></span><span><b>{thickness}</b><small>thickness</small></span><span><b>{mechanical.mounting_holes.length}</b><small>mounts</small></span><span><b>{mechanical.component_envelopes.length}</b><small>models</small></span><span><b>±{mm(mechanical.tolerances?.xy_nm||0)}</b><small>XY tol mm</small></span></div><span className="grow"/><button onClick={onValidate} disabled={disabled}>Validate</button><button onClick={()=>onSolid("dxf")} disabled={disabled}>DXF</button><button onClick={()=>onSolid("step")} disabled={disabled}>STEP</button><button onClick={onPreview} disabled={disabled}>Preview</button><button className="primary" onClick={onExport} disabled={disabled}>Envelope</button></div>
    <div className="mechanical-body" data-details={details}><div className="mechanical-stage">
      <div className="mechanical-view-tools"><button onClick={()=>setYaw(yaw-15)}>↶</button><code>{yaw}°</code><button onClick={()=>setYaw(yaw+15)}>↷</button><button onClick={()=>setElevation(Math.max(10,elevation-5))}>Lower</button><button onClick={()=>setElevation(Math.min(55,elevation+5))}>Higher</button><button data-active={showLabels} onClick={()=>setShowLabels(!showLabels)}>Labels</button><button data-active={showInterfaces} onClick={()=>setShowInterfaces(!showInterfaces)}>Interfaces</button><button data-active={showClearance} onClick={()=>setShowClearance(!showClearance)}>Clearances</button><button data-active={details} onClick={()=>setDetails(!details)}>Details</button></div>
      <svg viewBox="0 0 900 560" aria-label="Interactive PCB mechanical 3D assembly"><defs><linearGradient id="mech-board" x2="0" y2="1"><stop stopColor="#36a57f"/><stop offset="1" stopColor="#075f4c"/></linearGradient><filter id="mech-shadow"><feDropShadow dx="0" dy="13" stdDeviation="11" floodOpacity=".5"/></filter><filter id="mech-led-glow"><feDropShadow dx="0" dy="0" stdDeviation="3" floodColor="#4ade80" floodOpacity=".9"/></filter></defs><g filter="url(#mech-shadow)">
        <polygon points={points(outline,0)} fill="#064438" stroke="#4aa88f" strokeWidth="1.2"/>
        {outline.map((p,i)=>{const q=outline[(i+1)%outline.length],face=[project(mm(p.x_nm),mm(p.y_nm),0),project(mm(q.x_nm),mm(q.y_nm),0),project(mm(q.x_nm),mm(q.y_nm),thickness),project(mm(p.x_nm),mm(p.y_nm),thickness)].map(v=>v.map(n=>n.toFixed(1)).join(",")).join(" ");return <polygon key={i} points={face} fill="#075344" stroke="#51ad95" strokeWidth=".8"/>})}
        <polygon points={points(outline,thickness)} fill="url(#mech-board)" stroke="#73d5ba" strokeWidth="1.8"/>
        {definition.traces.filter(t=>t.layer==="F.Cu").map(t=><polyline key={t.id} points={points(t.points,thickness+.08)} fill="none" stroke="#c6a15a" strokeWidth={Math.max(.9,mm(t.width_nm)*scale)} strokeLinecap="round" strokeLinejoin="round" opacity=".82"><title>{t.net_id} · {t.id}</title></polyline>)}
        {definition.components.flatMap(c=>(c.pads||[]).filter(p=>p.layers.includes("F.Cu")).map(p=>{const a=(c.position.rotation_udeg||0)/1e6*Math.PI/180,px=c.position.x_nm+p.x_nm*Math.cos(a)-p.y_nm*Math.sin(a),py=c.position.y_nm+p.x_nm*Math.sin(a)+p.y_nm*Math.cos(a),[x,y]=project(mm(px),mm(py),thickness+.12),rx=Math.max(1.6,mm(p.width_nm)*scale*.5),ry=Math.max(1,mm(p.height_nm)*scale*.24);return <g key={`${c.id}:${p.id}`}><ellipse cx={x} cy={y} rx={rx} ry={ry} fill="#d2ad62" stroke="#604a25" strokeWidth=".7"/>{p.drill_nm&&<ellipse cx={x} cy={y} rx={Math.max(.7,mm(p.drill_nm)*scale*.42)} ry={Math.max(.4,mm(p.drill_nm)*scale*.2)} fill="#080907"/>}</g>}))}
        {showLabels&&definition.components.map(c=>{const [x,y]=project(mm(c.position.x_nm),mm(c.position.y_nm),thickness+.3);return <text key={c.id} x={x} y={y} fill="#e5dfd2" fontSize="7" textAnchor="middle" paintOrder="stroke" stroke="#0d1713" strokeWidth="2">{c.designator}</text>})}
        {mechanical.mounting_holes.map(h=>{const [x,y]=project(mm(h.x_nm),mm(h.y_nm),thickness+.02),r=Math.max(4,mm(h.diameter_nm)*scale*.5);return <g key={h.id} onClick={()=>setSelected(h.id)}><ellipse cx={x} cy={y} rx={r} ry={r*.46} fill="#070706" stroke="#d9c890" strokeWidth="2"/><title>{h.id} · {mm(h.diameter_nm)} mm · {h.fastener}</title></g>})}
        {mechanical.component_envelopes.map(e=><MechanicalPart key={e.id} item={e} project={project} selected={selected===e.id} showLabel={showLabels} onSelect={()=>setSelected(e.id)}/>) }
        {showClearance&&mechanical.clearance_zones.map(z=><MechanicalBox key={z.id} item={{...z,label:z.kind.replaceAll("_"," ")}} project={project} clearance selected={selected===z.id} onSelect={()=>setSelected(z.id)}/>) }
        {showInterfaces&&mechanical.panel_openings.map(o=>{const [x,y]=project(mm(o.x_nm),mm(o.y_nm),mm(o.z_nm));return <g key={o.id} onClick={()=>setSelected(o.id)}><circle cx={x} cy={y} r="6" fill="#d8b07a" stroke="#25170f" strokeWidth="2"/><path d={`M${x-10} ${y}H${x+10}M${x} ${y-10}V${y+10}`} stroke="#d8b07a" strokeWidth="1.5"/><title>{o.id} · {o.face} panel opening</title></g>})}
      </g><g transform="translate(24 488)"><rect width="852" height="48" rx="12" fill="#100e0c" stroke="#39342e"/><circle cx="25" cy="24" r="6" fill={validation?.status==="failed"?"#fb7185":validation?"#4ade80":"#eab308"}/><text x="43" y="21" fill="#f1ece6" fontSize="12" fontWeight="700">{validation?`${validation.status} · ${validation.errors} errors · ${validation.warnings} warnings`:"Mechanical validation not run"}</text><text x="43" y="36" fill="#928a81" fontSize="9">{mechanical.datum.origin} · +Z {mechanical.datum.z_axis}</text></g></svg>
    </div>{details&&<aside className="mechanical-inspector"><div className="mech-section"><Label>Mechanical objects</Label><button className="object-add" onClick={addHole}>+ Mounting hole</button><button className="object-add" onClick={addOpening}>+ Connector opening</button><button className="object-add" onClick={addClearance}>+ Clearance volume</button></div><div className="mech-section"><Label>Native component models</Label>{mechanical.component_envelopes.map(e=><button className="mech-object" data-active={selected===e.id} key={e.id} onClick={()=>setSelected(e.id)}><span><b>{e.label||e.id}</b><small>{e.model_ref?.replace("apteva://mechanical/","")||e.kind||"component"}</small></span><code>{mm(e.width_nm)}×{mm(e.depth_nm)}×{mm(e.z_max_nm-e.z_min_nm)}</code></button>)}</div>{selectedEnvelope&&<div className="mech-section"><Label>Selected solid</Label><Row label="ID" value={selectedEnvelope.id}/><Row label="Model" value={selectedEnvelope.model_ref||"native primitive"}/><label className="mech-field"><span>Height above datum (mm)</span><input type="number" min="0.1" step="0.1" value={mm(selectedEnvelope.z_max_nm-selectedEnvelope.z_min_nm)} onChange={e=>setHeight(selectedEnvelope.id,Number(e.target.value))}/></label></div>}<div className="mech-section"><Label>Handoff contract</Label><p className="muted">JSON and DXF carry source hash, datum, exact profile, openings, clearances and tolerances. STEP AP242 carries named faceted BREP solids; STL/3MF remain review meshes.</p></div></aside>}</div>
  </div>
}

function MechanicalPart({item,project,selected,showLabel,onSelect}:{item:MechanicalSpec["component_envelopes"][number];project:(x:number,y:number,z:number)=>[number,number];selected:boolean;showLabel:boolean;onSelect:()=>void}){
  const model=item.model_ref||"",gpio=model.includes("gpio"),dht=model.includes("dht22"),esp=model.includes("esp32"),jst=model.includes("jst-xh"),dualUSB=model.includes("dual-usb"),rj45=model.includes("rj45"),trrs=model.includes("trrs"),ffc=model.includes("ffc"),led=model.includes("led-0603"),chip=/bga|processor|memory|sot23|dfn/.test(model),metal=/usb|hdmi|rj45|micro-sd/.test(model),fill=dht?"#d9e7e4":jst?"#ddd7c7":esp?"#173c34":metal?"#aeb8bd":gpio?"#202427":chip?"#17191b":led?"#2b573a":"#3b4145",stroke=dht?"#f4faf7":jst?"#f5f0de":metal?"#e4eaed":gpio?"#9b854e":"#77828a",z=mm(item.z_max_nm)+.35,cx=mm(item.x_nm),cy=mm(item.y_nm);
  const screen=project(cx,cy,z),line=(key:string,x0:number,y0:number,x1:number,y1:number,color="#66726f",width=1.4)=>{const a=project(cx+x0,cy+y0,z),b=project(cx+x1,cy+y1,z);return <line key={key} x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke={color} strokeWidth={width} strokeLinecap="round"/>};
  const shield={...item,id:item.id+"-shield",label:"",x_nm:item.x_nm,y_nm:item.y_nm,z_min_nm:item.z_max_nm-800000,z_max_nm:item.z_max_nm+180000,width_nm:Math.round(item.width_nm*.78),depth_nm:Math.round(item.depth_nm*.68)};
  return <g><MechanicalBox item={item} project={project} selected={selected} onSelect={onSelect} fill={fill} stroke={stroke} showLabel={showLabel}/>
    {gpio&&Array.from({length:40},(_,i)=>{const column=i%20,row=Math.floor(i/20),x=mm(item.x_nm-item.width_nm*.45+column*item.width_nm*.9/19),y=mm(item.y_nm-item.depth_nm*.2+row*item.depth_nm*.4),p=project(x,y,z);return <ellipse key={i} cx={p[0]} cy={p[1]} rx="1.8" ry=".95" fill="#d6ad54" stroke="#72551f"/>})}
    {esp&&<g pointerEvents="none"><MechanicalBox item={shield} project={project} selected={false} onSelect={()=>{}} fill="#b7bec0" stroke="#e6ebec" showLabel={false}/>{[-.38,-.2,0,.2,.38].map((n,i)=>line(`ant-${i}`,-item.width_nm/2e6*.42,item.depth_nm/2e6*n,item.width_nm/2e6*.05,item.depth_nm/2e6*n,"#d4b25e",1.1))}<text x={screen[0]} y={screen[1]} fill="#303639" fontSize="7" textAnchor="middle">ESP32-C3</text></g>}
    {dht&&<g pointerEvents="none">{[-.34,-.22,-.1,.02,.14,.26,.38].map((n,i)=>line(`vent-${i}`,-item.width_nm/2e6*.36,item.depth_nm/2e6*n,item.width_nm/2e6*.36,item.depth_nm/2e6*n,"#708582",2.1))}<text x={screen[0]} y={screen[1]-5} fill="#415451" fontSize="8" fontWeight="700" textAnchor="middle">DHT22</text></g>}
    {jst&&<g pointerEvents="none">{Array.from({length:4},(_,i)=>{const p=project(cx-item.width_nm/2e6*.31+i*item.width_nm/2e6*.205,cy,z+.1);return <ellipse key={i} cx={p[0]} cy={p[1]} rx="4" ry="2" fill="#4c4a44" stroke="#f0ead9"/>})}</g>}
    {dualUSB&&<g pointerEvents="none"><rect x={screen[0]-13} y={screen[1]-9} width="26" height="7" rx="1.5" fill={model.includes("blue")?"#315f86":"#25282a"} stroke="#d5dde0"/><rect x={screen[0]-13} y={screen[1]+2} width="26" height="7" rx="1.5" fill={model.includes("blue")?"#315f86":"#25282a"} stroke="#d5dde0"/></g>}
    {rj45&&<g pointerEvents="none"><rect x={screen[0]-15} y={screen[1]-7} width="30" height="14" rx="2" fill="#252a2d" stroke="#d5dde0"/><circle cx={screen[0]-10} cy={screen[1]-9} r="2" fill="#7cbf66"/><circle cx={screen[0]+10} cy={screen[1]-9} r="2" fill="#d8b15a"/></g>}
    {trrs&&<g pointerEvents="none"><ellipse cx={screen[0]} cy={screen[1]} rx="10" ry="6" fill="#202427" stroke="#e2e7e9" strokeWidth="2"/><ellipse cx={screen[0]} cy={screen[1]} rx="4" ry="2.4" fill="#080909"/></g>}
    {ffc&&<g pointerEvents="none">{line("ffc-latch",-item.width_nm/2e6*.42,0,item.width_nm/2e6*.42,0,"#d8c58c",4)}</g>}
    {chip&&<g pointerEvents="none"><rect x={screen[0]-8} y={screen[1]-4} width="16" height="8" rx="1" fill="#25282b" stroke="#6f767a"/>{line("chip-mark",-item.width_nm/2e6*.26,-item.depth_nm/2e6*.22,item.width_nm/2e6*.26,-item.depth_nm/2e6*.22,"#72797c",.8)}</g>}
    {led&&<g pointerEvents="none"><ellipse cx={screen[0]} cy={screen[1]} rx="5" ry="2.8" fill="#55d47a" stroke="#d9f8df" filter="url(#mech-led-glow)"/></g>}
    {!gpio&&!dht&&!esp&&!jst&&!dualUSB&&!rj45&&!trrs&&!ffc&&!chip&&!led&&metal&&<g pointerEvents="none"><rect x={screen[0]-8} y={screen[1]-3} width="16" height="6" rx="2" fill="#30363a" stroke="#d7dee1"/></g>}
  </g>
}

function MechanicalBox({item,project,clearance=false,selected,onSelect,fill:customFill,stroke:customStroke,showLabel=true}:{item:{id:string;label?:string;x_nm:number;y_nm:number;z_min_nm:number;z_max_nm:number;width_nm:number;depth_nm:number;rotation_udeg?:number};project:(x:number,y:number,z:number)=>[number,number];clearance?:boolean;selected:boolean;onSelect:()=>void;fill?:string;stroke?:string;showLabel?:boolean}){
  const cx=mm(item.x_nm),cy=mm(item.y_nm),hw=mm(item.width_nm)/2,hd=mm(item.depth_nm)/2,angle=(item.rotation_udeg||0)/1e6*Math.PI/180,rot=(x:number,y:number):[number,number]=>[cx+x*Math.cos(angle)-y*Math.sin(angle),cy+x*Math.sin(angle)+y*Math.cos(angle)],corners=[rot(-hw,-hd),rot(hw,-hd),rot(hw,hd),rot(-hw,hd)],z0=mm(item.z_min_nm),z1=mm(item.z_max_nm),base=corners.map(p=>project(p[0],p[1],z0)),top=corners.map(p=>project(p[0],p[1],z1)),pts=(p:[number,number][])=>p.map(v=>v.map(n=>n.toFixed(1)).join(",")).join(" "),fill=customFill|| (clearance?"#b27a53":"#31363a"),stroke=selected?"#ffffff":customStroke||(clearance?"#c59a7b":"#849099"),opacity=clearance ? 0.16 : 1,center=project(cx,cy,z1+.7);
  const [a0,b0,c0,d0]=base,[a,b,c,d]=top;
  return <g className="mech-solid" data-selected={selected} opacity={opacity} onClick={e=>{e.stopPropagation();onSelect()}}><polygon points={pts([a0,b0,b,a])} fill={fill} stroke={stroke}/><polygon points={pts([b0,c0,c,b])} fill={fill} opacity=".76" stroke={stroke}/><polygon points={pts([c0,d0,d,c])} fill={fill} opacity=".58" stroke={stroke}/><polygon points={pts([a,b,c,d])} fill={fill} stroke={stroke} strokeWidth={selected?2:1.1}/>{showLabel&&item.label&&<text x={center[0]} y={center[1]} textAnchor="middle" fill="#fff" fontSize="8" paintOrder="stroke" stroke="#111" strokeWidth="2">{item.label}</text>}<title>{item.label||item.id}</title></g>
}

function WiringLab({definition,preview,result,onRun,onExport,disabled}:{definition:Definition;preview:string;result:WiringSimulation|null;onRun:()=>void;onExport:(format:string)=>void;disabled:boolean}){
  const wiring=definition.wiring;
  if(!wiring)return <div className="lab wiring-lab"><div className="empty-lab"><b>No wiring view in this revision</b><p>Create the Arduino Uno + LED example or add a native <code>wiring</code> object programmatically. The board layout and wiring illustration remain separate views of one revision.</p></div></div>;
  return <div className="lab wiring-lab"><div className="lab-toolbar"><div><small>Native physical wiring</small><strong>{wiring.parts.length} parts · {wiring.wires.length} pin-connected jumpers · {wiring.steps?.length||0} tutorial steps</strong></div><span className="grow"/><button onClick={()=>onExport("svg")} disabled={disabled}>Refresh visual</button><button onClick={()=>onExport("png")} disabled={disabled}>PNG</button><button onClick={()=>onExport("tutorial-zip")} disabled={disabled}>Tutorial ZIP</button><button className="primary" onClick={onRun} disabled={disabled}>Run Arduino sketch</button></div><div className="wiring-body"><div className="wiring-stage">{preview?<img src={preview} alt="Arduino Uno connected to a breadboard, resistor, and LED"/>:<div className="wiring-generate"><PCBMark/><b>Native wiring model is ready</b><p>Generate the detailed SVG illustration from the revisioned parts and pins.</p><button className="primary" onClick={()=>onExport("svg")} disabled={disabled}>Generate illustration</button></div>}</div><aside className="tutorial-steps"><div className={`wiring-state ${result?.part_states?.led1?.active?"lit":""}`}><i/><span><small>Virtual LED</small><b>{result?.part_states?.led1?.active?"ON · pin 9 HIGH":"Ready to simulate"}</b></span></div><Label>Build steps</Label>{wiring.steps?.map((step,index)=><div className="tutorial-step" key={step.id}><b>{index+1}</b><span><strong>{step.title}</strong><small>{step.instruction}</small></span></div>)}<div className="pin-contract"><b>Semantic, not decorative</b><p>Every wire ends at a named library pin. Validation, firmware state, SVG, PNG, and tutorial exports all read this same model.</p></div></aside></div></div>
}

function RouteLab({definition,plan,onAnalyze,onApply,disabled}:{definition:Definition;plan:RoutePlan|null;onAnalyze:()=>void;onApply:()=>void;disabled:boolean}){
  const preview=useMemo(()=>{const next=JSON.parse(JSON.stringify(definition)) as Definition;if(plan){for(const op of plan.operations){if(op.type==="trace.add"&&op.trace)next.traces.push(op.trace);if(op.type==="via.add"&&op.via)next.vias.push(op.via)}}return next},[definition,plan]);
  return <div className="lab route-lab"><div className="lab-toolbar"><div><small>Deterministic native router</small><strong>{plan?`${plan.status} · ${plan.metrics.routed_nets} routed`:"Analyze the current immutable revision"}</strong></div><span className="grow"/><button onClick={onAnalyze} disabled={disabled}>Analyze all nets</button><button className="primary" onClick={onApply} disabled={disabled||!plan||plan.status==="failed"||!plan.operations.length}>Apply route revision</button></div><div className="route-summary">{plan?<><Metric label="Grid" value={`${mm(plan.grid_nm)} mm`}/><Metric label="New traces" value={String(plan.metrics.trace_count)}/><Metric label="New vias" value={String(plan.metrics.via_count)}/><Metric label="Length" value={`${Math.round(plan.metrics.total_length_nm/1e6)} mm`}/><Metric label="Search" value={`${plan.metrics.visited_nodes} nodes`}/></>:<p className="muted">Routing proposals are reviewable typed operations. Manual traces remain untouched unless optimization is explicitly requested.</p>}</div>{plan?.failures?.map(f=><div className="route-failure" key={f.net_id}><b>{f.net_id}</b><span>{f.message}</span></div>)}<div className="lab-canvas"><BoardCanvas definition={preview}/></div></div>
}

function SimulationLab({result,onRun,disabled}:{result:SimulationResult|null;onRun:()=>void;disabled:boolean}){
  const rails=result?Object.entries(result.final_voltage_v).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,8):[];
  return <div className="lab simulation-lab"><div className="lab-toolbar"><div><small>Native electrical lab</small><strong>{result?`${result.samples} samples · ${result.duration_us/1000} ms`:`DC + transient RC + digital events`}</strong></div><span className="grow"/><button className="primary" onClick={onRun} disabled={disabled}>Run simulation</button></div>{!result?<div className="empty-lab"><b>Probe the board before fabrication</b><p>Saved sources and probes are read from the native revision. Results and waveforms are persisted through Storage.</p></div>:<><div className="rail-grid">{rails.map(([net,value])=><div className="rail" key={net}><small>{net}</small><b>{value.toFixed(3)} V</b><span data-state={result.final_digital[net]}>{result.final_digital[net]}</span></div>)}</div><div className="wave-grid">{result.waveforms.slice(0,6).map(w=><Waveform key={w.probe_id} waveform={w}/>)}</div>{result.warnings?.map(w=><div className="route-failure" key={w}>{w}</div>)}</>}</div>
}

function Waveform({waveform:w}:{waveform:SimulationResult["waveforms"][number]}){const width=300,height=74,values=w.points.map(p=>p.value),max=Math.max(...values,1),min=Math.min(...values,0),range=Math.max(.001,max-min),path=w.points.map((p,i)=>`${i?"L":"M"}${(i/Math.max(1,w.points.length-1))*width},${height-8-((p.value-min)/range)*(height-20)}`).join(" ");return <div className="wave"><div><b>{w.probe_id}</b><span>{w.net_id} · {w.unit}</span></div><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none"><path className="wave-gridline" d={`M0 ${height-8}H${width}M0 12H${width}`}/><path className="wave-line" d={path}/></svg></div>}

function FirmwareLab({source,setSource,result,onRun,disabled}:{source:string;setSource:(value:string)=>void;result:FirmwareResult|null;onRun:()=>void;disabled:boolean}){return <div className="lab firmware-lab"><div className="lab-toolbar"><div><small>Arduino-compatible virtual hardware</small><strong>{result?`${result.board} · ${result.runtime}`:"GPIO · Serial · I²C · virtual sensors"}</strong></div><span className="grow"/><button className="primary" onClick={onRun} disabled={disabled||!source.trim()}>Run sketch</button></div><div className="firmware-grid"><textarea className="firmware-source" spellCheck={false} value={source} onChange={e=>setSource(e.target.value)}/><div className="console"><div className="console-title"><b>Serial monitor</b><span>{result?.serial_baud||"—"} baud</span></div><pre>{result?.serial_output.join("\n")||"Run the sketch to open the virtual serial stream."}</pre>{result&&<div className="io-summary"><Metric label="Runtime" value={`${result.duration_us/1000} ms`}/><Metric label="GPIO high" value={String(Object.values(result.pin_states).filter(v=>v==="high").length)}/><Metric label="I²C transactions" value={String(result.i2c_transactions.length)}/><Metric label="I²C status" value={result.i2c_transactions.every(t=>t.status==="ack")?"ACK":"NACK"}/></div>}</div></div></div>}

function Metric({label,value}:{label:string;value:string}){return <div className="metric"><small>{label}</small><b>{value}</b></div>}

function BoardCanvas({definition:d,onChange,onUndo,onRedo,canUndo=false,canRedo=false}:{definition:Definition;onChange?:(next:Definition,label:string)=>void;onUndo?:()=>void;onRedo?:()=>void;canUndo?:boolean;canRedo?:boolean}){
  const editable=!!onChange,svgRef=useRef<SVGSVGElement|null>(null);
  const [front,setFront]=useState(true),[back,setBack]=useState(true),[zones,setZones]=useState(true),[keepouts,setKeepouts]=useState(true),[zoom,setZoom]=useState(1),[selected,setSelected]=useState<string>("");
  const [mode,setMode]=useState<"select"|"trace"|"via">("select"),[activeNet,setActiveNet]=useState(d.nets[0]?.id||""),[activeLayer,setActiveLayer]=useState("F.Cu"),[gridNM,setGridNM]=useState(500000),[manualPoints,setManualPoints]=useState<Point[]>([]),[draft,setDraft]=useState<Definition|null>(null);
  const [drag,setDrag]=useState<{id:string;start:Point;origin:{x_nm:number;y_nm:number};snapshot:Definition}|null>(null);
  useEffect(()=>{setDraft(null);setManualPoints([]);if(!d.nets.some(n=>n.id===activeNet))setActiveNet(d.nets[0]?.id||"")},[d]);
  const boardDef=draft||d,w=mm(boardDef.board.width_nm),h=mm(boardDef.board.height_nm),copperLayers=boardDef.board.layers.filter(l=>l.kind==="copper").map(l=>l.id);
  const netNames=useMemo(()=>Object.fromEntries(boardDef.nets.map(n=>[n.id,n.name])),[boardDef.nets]);
  const pts=(p:Point[])=>p.map(v=>`${mm(v.x_nm)},${mm(v.y_nm)}`).join(" ");
  const outline=boardDef.board.outline?.length?boardDef.board.outline:[{x_nm:0,y_nm:0},{x_nm:boardDef.board.width_nm,y_nm:0},{x_nm:boardDef.board.width_nm,y_nm:boardDef.board.height_nm},{x_nm:0,y_nm:boardDef.board.height_nm}];
  const layerVisible=(layer:string)=>layer==="F.Cu"?front:layer==="B.Cu"?back:true;
  const selectedComponent=selected.startsWith("component:")?boardDef.components.find(c=>c.id===selected.slice(10)):undefined;
  const selectedTrace=selected.startsWith("trace:")?boardDef.traces.find(t=>t.id===selected.slice(6)):undefined;
  const selectedVia=selected.startsWith("via:")?boardDef.vias.find(v=>v.id===selected.slice(4)):undefined;
  const snap=(value:number)=>Math.round(value/gridNM)*gridNM;
  function eventPoint(event:{clientX:number;clientY:number}){const svg=svgRef.current;if(!svg)return{x_nm:0,y_nm:0};const matrix=svg.getScreenCTM();if(!matrix)return{x_nm:0,y_nm:0};const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(matrix.inverse());return{x_nm:snap(Math.max(0,Math.min(boardDef.board.width_nm,Math.round(local.x*1e6)))),y_nm:snap(Math.max(0,Math.min(boardDef.board.height_nm,Math.round(local.y*1e6))))}}
  function commit(next:Definition,label:string){onChange?.(next,label);setDraft(null)}
  function beginDrag(event:React.PointerEvent<SVGGElement>,id:string){if(!editable||mode!=="select")return;event.stopPropagation();const component=boardDef.components.find(c=>c.id===id);if(!component)return;setSelected(`component:${id}`);setDrag({id,start:eventPoint(event),origin:{x_nm:component.position.x_nm,y_nm:component.position.y_nm},snapshot:JSON.parse(JSON.stringify(boardDef))})}
  function moveDrag(event:React.PointerEvent<SVGSVGElement>){if(!drag)return;const point=eventPoint(event),next=JSON.parse(JSON.stringify(drag.snapshot)) as Definition,component=next.components.find(c=>c.id===drag.id);if(!component)return;component.position.x_nm=snap(drag.origin.x_nm+point.x_nm-drag.start.x_nm);component.position.y_nm=snap(drag.origin.y_nm+point.y_nm-drag.start.y_nm);component.position.x_nm=Math.max(0,Math.min(next.board.width_nm,component.position.x_nm));component.position.y_nm=Math.max(0,Math.min(next.board.height_nm,component.position.y_nm));setDraft(next)}
  function endDrag(){if(drag&&draft)commit(draft,`Move ${draft.components.find(c=>c.id===drag.id)?.designator||drag.id}`);setDrag(null)}
  function boardClick(event:React.MouseEvent<SVGSVGElement>){if(!editable||drag)return;if(mode==="select"){setSelected("");return}const point=eventPoint(event);if(mode==="trace"){setManualPoints(points=>points.length&&points[points.length-1].x_nm===point.x_nm&&points[points.length-1].y_nm===point.y_nm?points:[...points,point]);return}if(mode==="via"&&activeNet&&copperLayers.length>1){const next=JSON.parse(JSON.stringify(boardDef)) as Definition,rule=next.net_classes?.find(c=>c.net_ids.includes(activeNet));next.vias.push({id:uniqueUIID(next.vias.map(v=>v.id),`manual-${activeNet}-v`),net_id:activeNet,x_nm:point.x_nm,y_nm:point.y_nm,diameter_nm:rule?.via_diameter_nm||650000,drill_nm:rule?.via_drill_nm||300000,from_layer:activeLayer,to_layer:copperLayers.find(l=>l!==activeLayer)||copperLayers[0]});commit(next,`Place ${activeNet} via`);setSelected("")}}
  function finishTrace(){if(!activeNet||manualPoints.length<2)return;const next=JSON.parse(JSON.stringify(boardDef)) as Definition,rule=next.net_classes?.find(c=>c.net_ids.includes(activeNet));next.traces.push({id:uniqueUIID(next.traces.map(t=>t.id),`manual-${activeNet}-t`),net_id:activeNet,layer:activeLayer,width_nm:rule?.trace_width_nm||next.rules.min_trace_width_nm,points:manualPoints});commit(next,`Draw ${activeNet} trace`);setManualPoints([]);setSelected("")}
  function rotateSelected(){if(!selectedComponent)return;const next=JSON.parse(JSON.stringify(boardDef)) as Definition,component=next.components.find(c=>c.id===selectedComponent.id);if(!component)return;component.position.rotation_udeg=(component.position.rotation_udeg+90000000)%360000000;commit(next,`Rotate ${component.designator}`)}
  function nudgeSelected(dx:number,dy:number){if(!selectedComponent)return;const next=JSON.parse(JSON.stringify(boardDef)) as Definition,component=next.components.find(c=>c.id===selectedComponent.id);if(!component)return;component.position.x_nm=Math.max(0,Math.min(next.board.width_nm,component.position.x_nm+dx*gridNM));component.position.y_nm=Math.max(0,Math.min(next.board.height_nm,component.position.y_nm+dy*gridNM));commit(next,`Nudge ${component.designator}`)}
  function deleteSelected(){const next=JSON.parse(JSON.stringify(boardDef)) as Definition;if(selectedTrace)next.traces=next.traces.filter(t=>t.id!==selectedTrace.id);else if(selectedVia)next.vias=next.vias.filter(v=>v.id!==selectedVia.id);else return;commit(next,`Delete ${selectedTrace?.id||selectedVia?.id}`);setSelected("")}
  function keyDown(event:React.KeyboardEvent<HTMLDivElement>){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="z"){event.preventDefault();event.shiftKey?onRedo?.():onUndo?.()}else if((event.key==="Delete"||event.key==="Backspace")&&(selectedTrace||selectedVia)){event.preventDefault();deleteSelected()}else if(event.key==="Escape"){setManualPoints([]);setMode("select")}}
  return <div className="viewport" tabIndex={0} onKeyDown={keyDown}>
    <div className="board-meta"><small>{editable?"Interactive native board":"Native board"}</small><b>{w} × {h} mm</b><span>{boardDef.components.reduce((n,c)=>n+(c.pads?.length||0),0)} pads · {boardDef.traces.length} traces · {boardDef.zones?.length||0} zones</span></div>
    {editable&&<div className="edit-tools"><div className="tool-segment"><button data-active={mode==="select"} onClick={()=>{setMode("select");setManualPoints([])}}>Select</button><button data-active={mode==="trace"} onClick={()=>setMode("trace")}>Trace</button><button data-active={mode==="via"} disabled={copperLayers.length<2} onClick={()=>{setMode("via");setManualPoints([])}}>Via</button></div><select aria-label="Active net" value={activeNet} onChange={e=>setActiveNet(e.target.value)}>{boardDef.nets.map(n=><option key={n.id} value={n.id}>{n.name||n.id}</option>)}</select><select aria-label="Active copper layer" value={activeLayer} onChange={e=>setActiveLayer(e.target.value)}>{copperLayers.map(layer=><option key={layer}>{layer}</option>)}</select><select aria-label="Editor grid" value={gridNM} onChange={e=>setGridNM(Number(e.target.value))}><option value={100000}>0.1 mm</option><option value={250000}>0.25 mm</option><option value={500000}>0.5 mm</option><option value={1000000}>1 mm</option></select>{mode==="trace"&&<><button className="primary" disabled={manualPoints.length<2} onClick={finishTrace}>Finish {manualPoints.length}</button><button onClick={()=>setManualPoints([])}>Cancel</button></>}<span className="tool-divider"/><button disabled={!canUndo} onClick={onUndo}>Undo</button><button disabled={!canRedo} onClick={onRedo}>Redo</button></div>}
    <div className="view-tools"><button data-active={front} onClick={()=>setFront(!front)}><i className="front"/>Top</button><button data-active={back} onClick={()=>setBack(!back)}><i className="back"/>Bottom</button><button data-active={zones} onClick={()=>setZones(!zones)}>Zones</button><button data-active={keepouts} onClick={()=>setKeepouts(!keepouts)}>Keepouts</button><button onClick={()=>setZoom(Math.max(.65,zoom-.15))}>−</button><code>{Math.round(zoom*100)}%</code><button onClick={()=>setZoom(Math.min(2.2,zoom+.15))}>+</button></div>
    <svg ref={svgRef} aria-label="Native PCB layout" className={editable?`editor-mode-${mode}`:""} style={{transform:`scale(${zoom})`}} viewBox={`-4 -4 ${w+8} ${h+8}`} onPointerMove={moveDrag} onPointerUp={endDrag} onPointerCancel={endDrag} onClick={boardClick}>
      <defs><linearGradient id="pcb-fill" x1="0" y1="0" x2="1" y2="1"><stop stopColor="#21170f"/><stop offset="1" stopColor="#130e0a"/></linearGradient><pattern id="pcb-grid" width="2" height="2" patternUnits="userSpaceOnUse"><path d="M2 0H0V2" fill="none" stroke="#d0ccc8" strokeOpacity=".055" strokeWidth=".04"/></pattern><pattern id="ko" width="1.4" height="1.4" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line y2="1.4" stroke="#fbbf24" strokeOpacity=".7" strokeWidth=".18"/></pattern></defs>
      <polygon className="board" points={pts(outline)}/><polygon points={pts(outline)} fill="url(#pcb-grid)"/>
      {zones&&(boardDef.zones||[]).filter(z=>layerVisible(z.layer)).map(z=><polygon className="zone" key={z.id} points={pts(z.polygon)} data-layer={z.layer}><title>{netNames[z.net_id]} zone · {z.layer}</title></polygon>)}
      {keepouts&&(boardDef.keepouts||[]).map(k=><polygon className="keepout" key={k.id} points={pts(k.polygon)}><title>{k.kind} keepout</title></polygon>)}
      {boardDef.traces.filter(t=>layerVisible(t.layer)).map(t=><g key={t.id} className="trace-object" data-selected={selected===`trace:${t.id}`} onClick={event=>{if(mode==="select"){event.stopPropagation();setSelected(`trace:${t.id}`)}}}><polyline points={pts(t.points)} fill="none" stroke="#1a0b04" strokeOpacity=".75" strokeWidth={mm(t.width_nm)+.16} strokeLinecap="round" strokeLinejoin="round"/><polyline className="trace" data-layer={t.layer} points={pts(t.points)} fill="none" strokeWidth={mm(t.width_nm)} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={t.layer==="B.Cu"?".55 .22":undefined}><title>{netNames[t.net_id]} · {t.layer} · {mm(t.width_nm)} mm</title></polyline></g>)}
      {manualPoints.length>0&&<polyline className="manual-preview" points={pts(manualPoints)} fill="none" strokeWidth={mm(boardDef.net_classes?.find(c=>c.net_ids.includes(activeNet))?.trace_width_nm||boardDef.rules.min_trace_width_nm)} strokeLinecap="round" strokeLinejoin="round"/>}
      {boardDef.vias.map(v=><g className="via-object" data-selected={selected===`via:${v.id}`} key={v.id} onClick={event=>{if(mode==="select"){event.stopPropagation();setSelected(`via:${v.id}`)}}}><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.diameter_nm)/2} fill="#d9b45b" stroke="#5d3f12" strokeWidth=".08"/><circle cx={mm(v.x_nm)} cy={mm(v.y_nm)} r={mm(v.drill_nm)/2} fill="#1a0b04"/><title>{netNames[v.net_id]} via · drill {mm(v.drill_nm)} mm</title></g>)}
      {boardDef.components.map(c=>{const body=c.body||{width_nm:3000000,height_nm:2000000};return <g className="footprint" data-selected={selected===`component:${c.id}`} key={c.id} onPointerDown={event=>beginDrag(event,c.id)} onClick={event=>{if(mode==="select"){event.stopPropagation();setSelected(`component:${c.id}`)}}} transform={`translate(${mm(c.position.x_nm)} ${mm(c.position.y_nm)}) rotate(${c.position.rotation_udeg/1e6})`}><rect className="component" x={-mm(body.width_nm)/2} y={-mm(body.height_nm)/2} width={mm(body.width_nm)} height={mm(body.height_nm)} rx=".25"/>{(c.pads||[]).filter(p=>p.layers.some(layerVisible)).map(p=>p.shape==="circle"?<circle className="pad" data-layer={p.layers.includes("F.Cu")?"F.Cu":"B.Cu"} key={p.id} cx={mm(p.x_nm)} cy={mm(p.y_nm)} r={mm(Math.min(p.width_nm,p.height_nm))/2}><title>{c.designator} pad {p.id} · pin {p.pin_id}</title></circle>:<rect className="pad" data-layer={p.layers.includes("F.Cu")?"F.Cu":"B.Cu"} key={p.id} x={mm(p.x_nm-p.width_nm/2)} y={mm(p.y_nm-p.height_nm/2)} width={mm(p.width_nm)} height={mm(p.height_nm)} rx={p.shape==="rect"?0:mm(Math.min(p.width_nm,p.height_nm))/4}><title>{c.designator} pad {p.id} · pin {p.pin_id}</title></rect>)}{(c.pads||[]).filter(p=>p.drill_nm).map(p=><circle className="drill" key={`${p.id}-drill`} cx={mm(p.x_nm)} cy={mm(p.y_nm)} r={mm(p.drill_nm||0)/2}/>)}<text y={-mm(body.height_nm)/2-.45} textAnchor="middle">{c.designator}</text><text className="value" y={mm(body.height_nm)/2+.62} textAnchor="middle">{c.value||c.name}</text><title>{c.designator} · {c.name} · {c.footprint}</title></g>})}
      <g className="dimensions"><path d={`M0 ${h+1.2}v1M${w} ${h+1.2}v1M0 ${h+1.7}H${w}`}/><text x={w/2} y={h+2.8} textAnchor="middle">{w} mm</text></g>
    </svg>
    {selectedComponent&&<div className="selection"><b>{selectedComponent.designator}</b><span>{selectedComponent.value||selectedComponent.name}</span><small>{selectedComponent.footprint} · {selectedComponent.pads?.length||0} pads · {selectedComponent.position.side}</small>{editable&&<div className="selection-actions"><button onClick={()=>nudgeSelected(-1,0)}>←</button><button onClick={()=>nudgeSelected(0,-1)}>↑</button><button onClick={()=>nudgeSelected(0,1)}>↓</button><button onClick={()=>nudgeSelected(1,0)}>→</button><button onClick={rotateSelected}>Rotate 90°</button></div>}</div>}
    {(selectedTrace||selectedVia)&&<div className="selection"><b>{selectedTrace?"Trace":"Via"}</b><span>{netNames[selectedTrace?.net_id||selectedVia?.net_id||""]}</span><small>{selectedTrace?`${selectedTrace.layer} · ${mm(selectedTrace.width_nm)} mm · ${selectedTrace.points.length} points`:`${selectedVia?.from_layer} → ${selectedVia?.to_layer} · ${mm(selectedVia?.drill_nm||0)} mm drill`}</small>{editable&&<button className="danger-edit" onClick={deleteSelected}>Delete object</button>}</div>}
    <div className="legend"><span><i className="front"/>F.Cu</span><span><i className="back"/>B.Cu</span><span><i className="pad-dot"/>pads</span><span><i className="keepout-dot"/>keepout</span></div>
  </div>
}
function uniqueUIID(existing:string[],prefix:string){let index=1,id=`${prefix}${index}`;while(existing.includes(id)){index++;id=`${prefix}${index}`}return id}
function Label({children}:{children:React.ReactNode}){return <div className="label">{children}</div>}
function Section({title,children}:{title:string;children:React.ReactNode}){return <section><Label>{title}</Label>{children}</section>}
function Row({label,value}:{label:string;value:string}){return <div className="row"><span>{label}</span><b>{value}</b></div>}
